package io.mavsdk.kotlin.plugins.gripper

import kotlin.coroutines.resume
import kotlinx.coroutines.suspendCancellableCoroutine

/** Allows users to send gripper actions. */
class Gripper internal constructor(private val native: GripperNative) {
    private var closed = false

    /** Possible results returned for gripper action requests. */
    enum class Result(val value: Int) {
        /** Unknown result */
        UNKNOWN(0),
        /** Request was successful */
        SUCCESS(1),
        /** No system is connected */
        NO_SYSTEM(2),
        /** Temporarily rejected */
        BUSY(3),
        /** Request timed out */
        TIMEOUT(4),
        /** Action not supported */
        UNSUPPORTED(5),
        /** Action failed */
        FAILED(6);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    /**
     * Gripper Actions.
     *
     * Available gripper actions are defined in mavlink under
     * https://mavlink.io/en/messages/common.html#GRIPPER_ACTIONS
     */
    enum class GripperAction(val value: Int) {
        /** Open the gripper to release the cargo */
        RELEASE(0),
        /** Close the gripper and grab onto cargo */
        GRAB(1);

        companion object {
            fun fromValue(value: Int): GripperAction =
                entries.find { it.value == value } ?: entries.first()
        }
    }

    /**
     * Gripper grab cargo.
     *
     * @param instance
     * @return The result of the request.
     */
    suspend fun grab(instance: Int): Result = suspendCancellableCoroutine { continuation ->
        val callbackGuard = GripperCallbackGuard()
        native.grabAsync(instance) { result ->
            val parsedResult = Result.fromValue(result)
            if (continuation.isActive && true && callbackGuard.tryClaim()) {
                continuation.resume(parsedResult)
            }
        }
    }

    /**
     * Gripper release cargo.
     *
     * @param instance
     * @return The result of the request.
     */
    suspend fun release(instance: Int): Result = suspendCancellableCoroutine { continuation ->
        val callbackGuard = GripperCallbackGuard()
        native.releaseAsync(instance) { result ->
            val parsedResult = Result.fromValue(result)
            if (continuation.isActive && true && callbackGuard.tryClaim()) {
                continuation.resume(parsedResult)
            }
        }
    }

    internal fun destroy() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class GripperException(val result: Result, message: String) : Exception(message)
}

internal interface GripperNative {
    fun grabAsync(instance: Int, callback: (Int) -> Unit)

    fun releaseAsync(instance: Int, callback: (Int) -> Unit)

    fun destroy()
}

internal expect fun createGripperNative(systemHandle: Long): GripperNative

internal expect class GripperCallbackGuard() {
    fun tryClaim(): Boolean
}
